{
  "analysis": "The GC fix script made things worse - it over-corrected by using too many GC-rich codons, creating 61 violations including high GC windows (38/50 = 76%). I need a completely different approach that targets ~50% GC balance rather than simply preferring GC-rich codons, with careful iterative fix-up that checks neighboring windows.",
  "plan": "I will write a new Python script that uses a balanced GC targeting algorithm: for each codon position, it picks the codon that brings the 50-nt window closest to 25 GC (50%), with heavy penalties for going outside the 15-35 range. Then it will iteratively fix any remaining violations by trying targeted codon swaps that fix one window without breaking neighbors.",
  "commands": [
    {
      "keystrokes": "cat > /app/design_gblock_v2.py <<'PY'
import csv, io, re

data = open('/app/fpbase_proteins.csv').read()
fpbase = {row['slug']: row for row in csv.DictReader(io.StringIO(data))}

pdb_data = open('/app/pdb_fasta_all.txt').read()
entries = {}
h, s = None, []
for line in pdb_data.strip().split('\n'):
    if line.startswith('>'):
        if h: entries.setdefault(h[1:5], []).append(''.join(s))
        h, s = line, []
    else: s.append(line.strip())
if h: entries.setdefault(h[1:5], []).append(''.join(s))

flag = "DYKDDDDK"
clover = fpbase['clover']['seq'][1:]
gb = open('/app/plasmid.gb').read()
dhfr = re.search(r'/translation="([^"]+)"', gb.replace('\n', ' ')).group(1).replace(' ', '')[1:]
mcherry = fpbase['mcherry']['seq'][1:]
mgmt = entries['3KZY'][0]
lnk = "GGGGSGGGGS"
fusion = flag + lnk + clover + lnk + dhfr + lnk + mcherry + lnk + mgmt

ct = {
    'A': ['GCT', 'GCA', 'GCC', 'GCG'], 'R': ['CGT', 'CGC', 'CGA', 'AGA', 'CGG', 'AGG'],
    'N': ['AAT', 'AAC'], 'D': ['GAT', 'GAC'], 'C': ['TGT', 'TGC'],
    'Q': ['CAA', 'CAG'], 'E': ['GAA', 'GAG'], 'G': ['GGT', 'GGA', 'GGC', 'GGG'],
    'H': ['CAT', 'CAC'], 'I': ['ATT', 'ATC', 'ATA'],
    'L': ['TTA', 'TTG', 'CTT', 'CTC', 'CTA', 'CTG'], 'K': ['AAA', 'AAG'],
    'M': ['ATG'], 'F': ['TTT', 'TTC'], 'P': ['CCT', 'CCA', 'CCC', 'CCG'],
    'S': ['TCT', 'TCA', 'AGT', 'TCC', 'TCG', 'AGC'], 'T': ['ACT', 'ACA', 'ACC', 'ACG'],
    'W': ['TGG'], 'Y': ['TAT', 'TAC'], 'V': ['GTT', 'GTA', 'GTC', 'GTG'],
}

def gc_count(s):
    return sum(1 for c in s if c in 'GC')

def window_penalty(gc_val):
    if gc_val < 15:
        return (15 - gc_val) ** 2 * 100
    elif gc_val > 35:
        return (gc_val - 35) ** 2 * 100
    else:
        return (gc_val - 25) ** 2

dna = []
for i, aa in enumerate(fusion):
    best, best_pen = None, 99999
    for codon in ct[aa]:
        temp = ''.join(dna) + codon
        L = len(temp)
        pen = 0
        for start in range(max(0, L - 50), L - 49):
            if start >= 0 and start + 50 <= L:
                pen += window_penalty(gc_count(temp[start:start+50]))
        if pen < best_pen:
            best_pen = pen
            best = codon
    dna.append(best)

dna_seq = ''.join(dna)

# Iterative fix-up
def find_violations(seq):
    return [i for i in range(len(seq) - 49) if gc_count(seq[i:i+50]) < 15 or gc_count(seq[i:i+50]) > 35]

for iteration in range(200):
    vols = find_violations(dna_seq)
    if not vols:
        print(f"All GC windows fixed after {iteration} iterations")
        break
    fixed = False
    for pos in vols:
        w = gc_count(dna_seq[pos:pos+50])
        need_higher = w < 15
        cstart = pos // 3
        cend = (pos + 50 + 2) // 3
        for cp in range(cstart, min(cend, len(fusion))):
            aa = fusion[cp]
            cur = dna_seq[3*cp:3*cp+3]
            cur_gc = gc_count(cur)
            candidates = []
            for nc in ct[aa]:
                if nc == cur: continue
                nc_gc = gc_count(nc)
                if need_higher and nc_gc > cur_gc:
                    candidates.append(nc)
                elif not need_higher and nc_gc < cur_gc:
                    candidates.append(nc)
            candidates.sort(key=lambda c: gc_count(c), reverse=need_higher)
            for nc in candidates:
                nd = dna_seq[:3*cp] + nc + dna_seq[3*cp+3:]
                new_vols = find_violations(nd)
                if len(new_vols) < len(vols):
                    dna_seq = nd
                    fixed = True
                    break
            if fixed: break
        if fixed: break
    if not fixed:
        print(f"Cannot fix all violations at iteration {iteration}, remaining: {len(vols)}")
        break

gc_code = {'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L','ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V','TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P','ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A','TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E','TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R','AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
tr = ''.join(gc_code[dna_seq[i:i+3]] for i in range(0, len(dna_seq), 3))

vols = find_violations(dna_seq)
print(f"Length: {len(dna_seq)} nt (max 3000: {'PASS' if len(dna_seq) <= 3000 else 'FAIL'})")
print(f"GC windows: {'PASS' if not vols else 'FAIL'} ({len(vols)} violations)")
for p in vols[:10]:
    print(f"  pos {p}: GC={gc_count(dna_seq[p:p+50])}/50")
print(f"Translation matches: {'PASS' if tr == fusion else 'FAIL'}")
print(f"No stop codons: {'PASS' if '*' not in tr else 'FAIL'}")
print(f"No start codon: {'PASS' if dna_seq[:3] != 'ATG' else 'FAIL'}")
print(f"No stop at end: {'PASS' if dna_seq[-3:] not in ['TAA','TAG','TGA'] else 'FAIL'}")

with open('/app/gblock.txt', 'w') as f:
    f.write(dna_seq)
print(f"Written {len(dna_seq)} nt to /app/gblock.txt")
